#include "CollisionAsset.h"
#include "CollisionGeometry.h"
#include <cstdio>
#include <memory>
#include <cmath>
#include <algorithm>
int main(int argc,char** argv){CollisionAsset asset;std::string error;if(!LoadCollisionAsset(argc>1?argv[1]:"projects/tuppence/Assets/collision/coin.judascollision",asset,error)){printf("FAIL %s\n",error.c_str());return 1;}const auto hull=Shape::Cooked(std::make_shared<CollisionAsset>(asset),"coin");unsigned checks=0,failures=0;{
 PrimitivePose coin,floor;coin.shape=hull;coin.parentPosition={0,.015f,0};coin.parentOrientation=glm::angleAxis(.1f,glm::vec3(1,0,0));floor.shape=Shape::Box({1,.1f,1});floor.parentPosition={0,-.1f,0};
 auto forward=CookedContacts(coin,floor,0),reverse=CookedContacts(floor,coin,0);
 printf("REFERENCE FACE forward=%d reversed=%d\n",forward.count,reverse.count);
 ++checks;if(forward.count<2||reverse.count<2){++failures;printf("FAIL swapping body order must retain a face support patch\n");}
 for(const auto* m:{&forward,&reverse})for(int k=0;k<m->count;++k){++checks;if(std::abs(m->points[k].point.x)>.3||std::abs(m->points[k].point.z)>.3){++failures;printf("FAIL face witnesses must lie under the actual coin footprint\n");}}
 }printf("SAT edges=%zu representative_directions=%zu\n",asset.edges.size(),asset.satEdges.size());CollisionAsset reference=asset;reference.satEdges.clear();for(unsigned i=0;i<reference.edges.size();++i)reference.satEdges.push_back(i);auto referenceShape=Shape::Cooked(std::make_shared<CollisionAsset>(reference),"full-edge reference");for(int i=0;i<240;++i){const auto frame=glm::angleAxis(float(i%7)*.19f,glm::normalize(glm::vec3(1,2,3)));PrimitivePose a,b;a.shape=hull;a.parentOrientation=frame*glm::angleAxis(float(i)*.013f,glm::normalize(glm::vec3(1,3,2)));b.shape=i%2?Shape::Box({1,.1f,1}):hull;b.parentOrientation=frame;auto offset=i%3?glm::vec3(0):glm::vec3(50000,-50000,50000);b.parentPosition=offset+frame*glm::vec3(0,i%2?-.1f:0,0);a.parentPosition=offset+frame*glm::vec3(float(i%9)*.03f,.02f+float(i%13-6)*.008f,0);for(bool reverse:{false,true}){const auto& x=reverse?b:a;const auto& y=reverse?a:b;auto m=CookedContacts(x,y,0);auto refX=x,refY=y;if(refX.shape.type==ShapeType::ConvexHull)refX.shape=referenceShape;if(refY.shape.type==ShapeType::ConvexHull)refY.shape=referenceShape;auto original=CookedContacts(refX,refY,0);++checks;if(bool(original.count)!=bool(m.count)){++failures;printf("FAIL parallel-axis contact truth case=%d\n",i);}double deep=0;for(int k=0;k<m.count;++k)deep=std::max(deep,-m.points[k].signedSeparation);for(double threshold:{0.,.001,.005,.02,deep,std::nextafter(deep,INFINITY),std::nextafter(deep,0.)}){++checks;bool actual=CookedHasPenetrationBeyond(x,y,threshold);if(actual!=(deep>threshold)){++failures;printf("FAIL case=%d reverse=%d depth=%.17g target=%.17g\n",i,int(reverse),deep,threshold);}}}}printf("SUMMARY checks=%u failures=%u\n",checks,failures);return failures?1:0;}
